function isSafeLine(line){return/<c:out\s+value=/.test(line)||/fn:escapeXml\s*\(/.test(line)||/escapeXml\s*=\s*["']true["']/.test(line)}function checkXssPatterns(filePath,content){const violations=[];const lines=content.split("\n");const scriptletPattern=/<%=\s*(?:request\.getParameter|request\.getAttribute|session\.getAttribute|cookie\s*\[|param\.)[^%]+%>/i;const elPattern=/\$\{\s*(?:param|requestScope|sessionScope|cookie)\./;for(let i=0;i<lines.length;i++){const line=lines[i];if(/^\s*<%--/.test(line)||/^\s*\/\//.test(line))continue;if(scriptletPattern.test(line)){violations.push({pattern:"scriptlet-direct-output",line:line.trim(),lineNo:i+1});continue}if(elPattern.test(line)&&!isSafeLine(line)){violations.push({pattern:"el-direct-output",line:line.trim(),lineNo:i+1})}}return{violations:violations}}function onPreToolUse(event){const{tool_name,tool_input}=event;if(!["edit","write"].includes((tool_name||"").toLowerCase())){return{decision:"allow"}}const filePath=tool_input.file_path||"";if(!filePath.endsWith(".jsp")&&!filePath.endsWith(".jspf")){return{decision:"allow"}}const content=(tool_name||"").toLowerCase()==="write"?tool_input.content||"":tool_input.new_string||"";if(!content)return{decision:"allow"};const{violations}=checkXssPatterns(filePath,content);if(violations.length===0)return{decision:"allow"};const lines=violations.map(v=>`  L${v.lineNo} [${v.pattern}]: ${v.line}`).join("\n");const message=`━━━ JSP XSS GUARD ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`+`File: ${filePath}\n\n`+`Unescaped user input detected (XSS risk):\n`+`${lines}\n\n`+`Fix options:\n`+`  1. <c:out value="\${...}"/>            (JSTL, recommended)\n`+`  2. \${fn:escapeXml(value)}             (function-based)\n`+`  3. <%= StringEscapeUtils.escapeHtml4(...) %>  (Apache Commons)\n\n`+`Reference: .claude/rules/validation.md (Boundary Validation)\n`+`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;return{decision:"block",message:message}}if(require.main===module){const chunks=[];process.stdin.setEncoding("utf8");process.stdin.on("data",c=>chunks.push(c));process.stdin.on("end",()=>{try{const input=chunks.join("");if(!input.trim())process.exit(0);const event=JSON.parse(input);const result=onPreToolUse(event);if(result.decision==="block"){if(result.message)process.stderr.write(result.message);process.exit(2)}process.exit(0)}catch(e){process.stderr.write(`[JspXssGuard] Parse error - allowing: ${e.message}\n`);process.exit(0)}});const safetyTimer=setTimeout(()=>{process.stderr.write("[JspXssGuard] stdin timeout - allowing\n");process.exit(0)},5e3);process.stdin.on("end",()=>clearTimeout(safetyTimer));process.stdin.resume()}module.exports={onPreToolUse:onPreToolUse,checkXssPatterns:checkXssPatterns,isSafeLine:isSafeLine};